import{_ as t,o as i,c as a,a2 as r}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"Guida utente","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/index.md","filePath":"user-guide/README.md"}'),o={name:"user-guide/index.md"};function d(n,e,l,s,c,p){return i(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="guida-utente" tabindex="-1">Guida utente <a class="header-anchor" href="#guida-utente" aria-label="Permalink to &quot;Guida utente&quot;">​</a></h1><p>Clarae notanda è un&#39;app per appunti e conoscenza personale che funziona <strong>offline</strong> su cartelle di file normali (<code>.md</code>, <code>.canvas</code>, <code>.base</code>, <code>.excalidraw</code>), compatibili con i vault di Obsidian. Il cloud è facoltativo: serve per sincronizzare più dispositivi e per condividere.</p><table tabindex="0"><thead><tr><th>Capitolo</th><th>Di cosa parla</th></tr></thead><tbody><tr><td><a href="./installazione.html">Installazione</a></td><td>Scaricare e installare l&#39;app su macOS, Windows, Linux; aggiornare dalla 1.x.</td></tr><tr><td><a href="./primo-vault.html">Il primo vault</a></td><td>Aprire una cartella, l&#39;interfaccia, creare le prime note.</td></tr><tr><td><a href="./scrivere-link-proprieta.html">Scrivere, link e proprietà</a></td><td>Modalità dell&#39;editor, wikilink, backlink, tag, proprietà.</td></tr><tr><td><a href="./ricerca.html">Ricerca</a></td><td>Selettore rapido, ricerca nel vault, operatori, ricerche incorporate.</td></tr><tr><td><a href="./canvas-disegni-bases-grafo.html">Lavagne, disegni, basi e grafo</a></td><td>Canvas, disegni Excalidraw, Bases, vista grafo.</td></tr><tr><td><a href="./template-note-giornaliere.html">Template e note giornaliere</a></td><td>Template, note giornaliere, note uniche, unire ed estrarre note.</td></tr><tr><td><a href="./presentazioni.html">Presentazioni</a></td><td>Slide da una nota o da un file <code>.marp</code>, note del relatore, tab Slideshow, export.</td></tr><tr><td><a href="./applicazioni.html">Applicazioni</a></td><td>Pagine web registrate nel vault (file <code>.webapp</code>) che si aprono in una scheda.</td></tr><tr><td><a href="./terminale.html">Terminale</a></td><td>Shell nel pannello e in una finestra separata, <strong>avvertenze di sicurezza</strong>, vault in sola lettura.</td></tr><tr><td><a href="./sync-cloud.html">Sincronizzazione e cloud</a></td><td>Collegarsi al server, sincronizzare, conflitti, più dispositivi.</td></tr><tr><td><a href="./vault-privati-condivisi.html">Vault privati e condivisi</a></td><td>Che cosa cambia, <strong>che cosa significa E2EE</strong>, passphrase e chiave di recupero.</td></tr><tr><td><a href="./condivisione-gruppi.html">Condivisione e gruppi</a></td><td>Inviti, permessi, mount, gruppi.</td></tr><tr><td><a href="./presenza.html">Presenza</a></td><td>Avatar e cursori degli altri utenti sullo stesso file, privacy, come si spegne.</td></tr><tr><td><a href="./import-export.html">Importare ed esportare</a></td><td>Importer (Markdown, Evernote, Notion, Roam, Bear, Keep, CSV), PDF, HTML, ZIP.</td></tr><tr><td><a href="./cronologia-recupero.html">Cronologia e recupero</a></td><td>Versioni locali e del cloud, ripristino, file eliminati.</td></tr><tr><td><a href="./impostazioni-scorciatoie.html">Impostazioni e scorciatoie</a></td><td>Tutte le impostazioni, comandi e scorciatoie predefinite.</td></tr><tr><td><a href="./accessibilita.html">Accessibilità</a></td><td>Tastiera, screen reader, contrasto elevato, movimento ridotto.</td></tr><tr><td><a href="./risoluzione-problemi.html">Risoluzione dei problemi</a></td><td>Sintomi comuni e come risolverli.</td></tr></tbody></table><p>Convenzioni: <strong>Mod</strong> indica <code>Cmd</code> su macOS e <code>Ctrl</code> su Windows/Linux. I nomi dei comandi sono quelli della palette comandi (<code>Mod+P</code>), dove si può cercare qualsiasi azione.</p><blockquote><p>Vault privati: se perdete passphrase <strong>e</strong> chiave di recupero, nessuno può recuperare i dati, nemmeno l&#39;amministratore. Leggete <a href="./vault-privati-condivisi.html">Vault privati e condivisi</a> prima di creare il primo.</p></blockquote>',5)])])}const h=t(o,[["render",d]]);export{m as __pageData,h as default};
